def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_last, opp_last = history[-1]

    c_opp = 0
    for i in range(n):
        if history[i][1] == 'C':
            c_opp += 1
    d_opp = n - c_opp
    coop_rate = c_opp / n

    streak_d = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        streak_d += 1
        i -= 1

    streak_c = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'C':
        streak_c += 1
        i -= 1

    recent_start = n - 10
    if recent_start < 0:
        recent_start = 0
    recent_d = 0
    for i in range(recent_start, n):
        if history[i][1] == 'D':
            recent_d += 1

    tol = 0
    pun = 0
    for i in range(1, n):
        pm, po = history[i - 1]
        if pm == 'D' and po == 'C':
            if history[i][1] == 'C':
                tol += 1
            else:
                pun += 1

    unresolved = my_last == 'D' and opp_last == 'C'
    just_punished = (
        n >= 2 and
        my_last == 'C' and
        opp_last == 'D' and
        history[-2][0] == 'D' and
        history[-2][1] == 'C'
    )

    mirror = 0
    mirror_len = n - 1
    if mirror_len > 0:
        for i in range(1, n):
            if history[i][1] == history[i - 1][0]:
                mirror += 1
    is_mirror = mirror_len >= 8 and mirror * 100 >= mirror_len * 70

    alt = 0
    if n >= 8:
        for i in range(1, n):
            if history[i][1] != history[i - 1][1]:
                alt += 1
    is_alt = n >= 8 and alt * 100 >= (n - 1) * 85 and not is_mirror

    exploit_conf = (tol >= 1 and pun == 0) or (tol >= 2 and pun <= 1 and coop_rate > 0.8)

    if unresolved:
        if exploit_conf and coop_rate > 0.7:
            return 'D'
        if n >= 92:
            return 'D'
        if coop_rate < 0.5:
            return 'D'
        return 'C'

    if just_punished:
        if is_mirror and coop_rate > 0.3:
            return 'C'
        if coop_rate > 0.45 and streak_d == 1 and recent_d <= 1:
            return 'C'
        return 'D'

    if c_opp == 0:
        return 'D'

    if exploit_conf:
        if opp_last == 'C' and streak_d == 0:
            return 'D'

    if d_opp == 0:
        if n >= 55:
            return 'D'
        if n >= 30 and rng.random() < 0.06:
            return 'D'
        return 'C'

    if recent_d >= 8 or (recent_d >= 5 and coop_rate < 0.45):
        return 'D'

    if is_mirror:
        if opp_last == 'C':
            return 'C'
        if streak_d == 1:
            if my_last == 'D' and coop_rate >= 0.4:
                return 'C'
            if coop_rate >= 0.55 and recent_d <= 2:
                return 'C'
            return 'D'
        if streak_d >= 2:
            return 'D'
        return 'C'

    if is_alt:
        return 'D'

    if opp_last == 'D':
        if streak_d >= 2:
            if my_last == 'C' and coop_rate > 0.6 and recent_d <= 2:
                return 'C'
            return 'D'

        if my_last == 'D':
            if coop_rate >= 0.4:
                return 'C'
            return 'D'

        if coop_rate > 0.75 and recent_d <= 1:
            return 'D'
        if rng.random() < 0.2 and coop_rate > 0.5:
            return 'C'
        return 'D'

    if coop_rate <= 0.3:
        return 'D'

    if coop_rate >= 0.8:
        if n >= 90 and recent_d <= 1 and rng.random() < 0.35:
            return 'D'
        return 'C'

    if coop_rate <= 0.5:
        if recent_d >= 2:
            return 'D'
        return 'C'

    if recent_d <= 1:
        return 'C'
    if rng.random() < 0.25:
        return 'C'
    return 'D'
